<?php
declare(strict_types=1); require_once __DIR__.'/../includes/layout.php'; require_admin();$q=trim((string)($_GET['q']??''));$status=(string)($_GET['status']??'');$sql="SELECT r.*,b.title,COALESCE(u.fullname,r.walkin_name) customer,COALESCE(u.phone,r.walkin_phone) contact FROM rentals r JOIN books b ON b.id=r.book_id LEFT JOIN users u ON u.id=r.user_id WHERE (COALESCE(u.fullname,r.walkin_name) LIKE ? OR b.title LIKE ?)";$args=["%$q%","%$q%"];
if(in_array($status,['borrowed','returned'],true)){$sql.=' AND r.status=?';$args[]=$status;}$sql.=' ORDER BY r.borrowed_at DESC';$s=db()->prepare($sql);$s->execute($args);$rows=$s->fetchAll();page_start('ประวัติการเช่า','history'); ?>
<div class="page-head"><div><h1>ประวัติการเช่า</h1><p>รายการเช่าทั้งจากการจองออนไลน์และหน้าร้าน</p></div></div><form class="filters"><input name="q" value="<?=e($q)?>" placeholder="ค้นหาลูกค้าหรือหนังสือ"><select name="status"><option value="">ทุกสถานะ</option><option value="borrowed" <?=$status==='borrowed'?'selected':''?>>กำลังยืม</option><option value="returned" <?=$status==='returned'?'selected':''?>>คืนแล้ว</option></select><button class="btn">ค้นหา</button></form><section class="panel"><div class="table-wrap"><table><thead><tr><th>ลูกค้า / ติดต่อ</th><th>หนังสือ</th><th>แหล่งที่มา</th><th>เริ่มเช่า</th><th>กำหนดคืน</th><th>คืนจริง</th><th>ค่าเช่า</th><th>ค่าปรับ</th><th>สถานะ</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['customer'])?><br><small><?=e($r['contact'])?></small></td><td><?=e($r['title'])?></td><td><?=$r['source']==='online_reservation'?'Online Reservation':'Walk-in'?></td><td><?=thai_date($r['borrowed_at'],true)?></td><td><?=thai_date($r['due_date'])?></td><td><?=thai_date($r['returned_at'],true)?></td><td><?=format_money($r['rental_total'])?></td><td><?=format_money($r['fine'])?></td><td><?=status_badge($r['status'],rental_label($r['status']))?></td></tr><?php endforeach?><?php if(!$rows):?><tr><td colspan="9" class="empty">ไม่พบประวัติการเช่า</td></tr><?php endif?></tbody></table></div></section>
<?php page_end(); ?>

